struct NestedSolids;
impl ProgressStyle for NestedSolids {
    fn name(&self) -> &str {
        "nested-solids"
    }
    fn theme(&self) -> &str {
        "platonic"
    }
    fn describe(&self) -> &str {
        "Nested duals: a cube spinning inside its dual octahedron — both rotating at different rates, revealed in two waves"
    }
    fn render(&self, grid: &mut BrailleGrid, ctx: &BarContext) -> Result<(), DotmaxError> {
        let (cx, cy, scale) = stage(grid, ctx, 1.0);

        // Outer octahedron — slower rotation, revealed in first half of eased.
        let ax_oct = ctx.time * 0.27;
        let ay_oct = ctx.time * 0.41;
        let view_oct = View {
            ax: ax_oct,
            ay: ay_oct,
            cx,
            cy,
            scale,
        };
        let pts_oct = project_verts(&OCTA_VERTS, &view_oct);

        // Inner cube — faster rotation, revealed in second half, scaled to inradius.
        // Inradius of octahedron = 1/√3 ≈ 0.577, so cube circumradius ≈ 0.577.
        let cube_inner_scale = scale * 0.577_350_3; // fit cube inside octahedron
        let ax_cube = ctx.time * 0.55;
        let ay_cube = ctx.time * 0.71;
        let view_cube = View {
            ax: ax_cube,
            ay: ay_cube,
            cx,
            cy,
            scale: cube_inner_scale,
        };
        let pts_cube = project_verts(&CUBE_VERTS, &view_cube);

        let n_show = reveal(ctx, OCTA_EDGES.len() + CUBE_EDGES.len());
        let n_oct = n_show.min(OCTA_EDGES.len());
        let n_cube = n_show.saturating_sub(OCTA_EDGES.len());

        draw_edges_partial(grid, &pts_oct, &OCTA_EDGES, n_oct);
        draw_edges_partial(grid, &pts_cube, &CUBE_EDGES, n_cube);
        Ok(())
    }
}

/// Face centres of the dodecahedron (approximate — used as spike bases).
/// The dodecahedron has 12 pentagonal faces; their centres lie along the 12
/// icosahedron vertices (the dual relationship).  We scale icosahedron verts
/// to get spike tips.
struct StellatedDodecahedron;
impl ProgressStyle for StellatedDodecahedron {
    fn name(&self) -> &str {
        "stellated-dodecahedron"
    }
    fn theme(&self) -> &str {
        "platonic"
    }
    fn describe(&self) -> &str {
        "Great stellated dodecahedron {5/2, 3}: the dodecahedron's 20 vertices joined \
         by 30 long edges into twelve interlocking pentagrams — a spinning star"
    }
    fn render(&self, grid: &mut BrailleGrid, ctx: &BarContext) -> Result<(), DotmaxError> {
        let (cx, cy, scale) = stage(grid, ctx, DODECA_SCALE);
        let ax = ctx.time * 0.25;
        let ay = ctx.time * 0.43;
        let view = View {
            ax,
            ay,
            cx,
            cy,
            scale,
        };
        let pts = project_verts(&DODECA_VERTS, &view);

        // The great stellated dodecahedron shares the dodecahedron's vertices;
        // its edges join vertex pairs φ² dodecahedron-edges apart (three per
        // vertex, thirty in all), tracing a pentagram on every face plane.
        let dist = |a: [f32; 3], b: [f32; 3]| {
            ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
        };
        let mut edge = f32::MAX;
        for (i, &va) in DODECA_VERTS.iter().enumerate() {
            for &vb in &DODECA_VERTS[i + 1..] {
                edge = edge.min(dist(va, vb));
            }
        }
        let long = edge * PHI * PHI;
        let mut star_edges: Vec<(usize, usize)> = Vec::with_capacity(30);
        for (i, &va) in DODECA_VERTS.iter().enumerate() {
            for (j, &vb) in DODECA_VERTS.iter().enumerate().skip(i + 1) {
                if (dist(va, vb) - long).abs() < long * 0.02 {
                    star_edges.push((i, j));
                }
            }
        }
        let n_show = reveal(ctx, star_edges.len());
        draw_edges_partial(grid, &pts, &star_edges, n_show);
        Ok(())
    }
}

struct UnfoldingNet;
impl ProgressStyle for UnfoldingNet {
    fn name(&self) -> &str {
        "unfolding-net"
    }
    fn theme(&self) -> &str {
        "platonic"
    }
    fn describe(&self) -> &str {
        "Cube net: a cross-shaped flat net folds progressively into a 3-D cube as progress advances — geometry becoming solid"
    }
    fn render(&self, grid: &mut BrailleGrid, ctx: &BarContext) -> Result<(), DotmaxError> {
        let (cx, cy, scale) = grid_centre_scale(grid, 0.68);
        // The flat cross is three faces tall; the folded cube only one, so the
        // camera closes in as the net folds to keep the cube filling the strip.
        let scale = scale * (1.0 + ctx.eased.clamp(0.0, 1.0) * 0.9);
        let ax = ctx.time * 0.30;
        let ay = ctx.time * 0.48;
        let t = ctx.eased; // 0 = flat net, 1 = cube

        // A standard cube cross-net has 6 faces.  We define each face by its
        // 4 corners in *net* space (flat) and in *cube* space (3-D).
        // We interpolate corners between flat and folded at parameter t.

        // Face corners in net space (centered at origin, side length 1).
        // Faces: bottom, front, right, left, back, top — standard cross layout.
        // Net layout (2D, z=0), face side = 1:
        //   [4]           top
        //   [2][0][1][3]  left, front, right, back
        //   [5]           bottom

        let half = 0.5_f32;

        // Net positions (flat, z=0) — each face's 4 corners (bl, br, tr, tl).
        let net: [[[f32; 3]; 4]; 6] = [
            // 0: front face (centre of cross, at (0,0)).
            [
                [-half, -half, 0.0],
                [half, -half, 0.0],
                [half, half, 0.0],
                [-half, half, 0.0],
            ],
            // 1: right face (at (1,0)).
            [
                [half, -half, 0.0],
                [3.0 * half, -half, 0.0],
                [3.0 * half, half, 0.0],
                [half, half, 0.0],
            ],
            // 2: left face (at (-1,0)).
            [
                [-3.0 * half, -half, 0.0],
                [-half, -half, 0.0],
                [-half, half, 0.0],
                [-3.0 * half, half, 0.0],
            ],
            // 3: back face (at (2,0)).
            [
                [3.0 * half, -half, 0.0],
                [5.0 * half, -half, 0.0],
                [5.0 * half, half, 0.0],
                [3.0 * half, half, 0.0],
            ],
            // 4: top face (at (0,1)).
            [
                [-half, half, 0.0],
                [half, half, 0.0],
                [half, 3.0 * half, 0.0],
                [-half, 3.0 * half, 0.0],
            ],
            // 5: bottom face (at (0,-1)).
            [
                [-half, -3.0 * half, 0.0],
                [half, -3.0 * half, 0.0],
                [half, -half, 0.0],
                [-half, -half, 0.0],
            ],
        ];

        // Cube corner positions for each face (fully folded).
        let cube: [[[f32; 3]; 4]; 6] = [
            // 0: front face z=+half (normal +z).
            [
                [-half, -half, half],
                [half, -half, half],
                [half, half, half],
                [-half, half, half],
            ],
            // 1: right face x=+half.
            [
                [half, -half, half],
                [half, -half, -half],
                [half, half, -half],
                [half, half, half],
            ],
            // 2: left face x=-half.
            [
                [-half, -half, -half],
                [-half, -half, half],
                [-half, half, half],
                [-half, half, -half],
            ],
            // 3: back face z=-half.
            [
                [half, -half, -half],
                [-half, -half, -half],
                [-half, half, -half],
                [half, half, -half],
            ],
            // 4: top face y=+half.
            [
                [-half, half, half],
                [half, half, half],
                [half, half, -half],
                [-half, half, -half],
            ],
            // 5: bottom face y=-half.
            [
                [-half, -half, -half],
                [half, -half, -half],
                [half, -half, half],
                [-half, -half, half],
            ],
        ];

        // Scale net so it fits the same display window as the folded cube.
        // Net spans from x=-1.5 to x=2.5 (4 units wide), y=-1.5 to y=1.5 (3 tall).
        // Cube spans ±0.5.  Map net scale to roughly 0.4 → 1.0 of display scale.
        let net_s = scale / 3.0;
        let cube_s = scale;
        // Scale: lerp from net_s to cube_s.
        let view = View {
            ax,
            ay,
            cx,
            cy,
            scale: net_s + (cube_s - net_s) * t,
        };

        for fi in 0..6usize {
            // Interpolate each corner between net and cube.
            let corners: Vec<(i32, i32)> = (0..4)
                .map(|ci| {
                    let [nx, ny, nz] = net[fi][ci];
                    let [cx2, cy2, cz] = cube[fi][ci];
                    let x = nx + (cx2 - nx) * t;
                    let y = ny + (cy2 - ny) * t;
                    let z = nz + (cz - nz) * t;
                    project(x, y, z, &view)
                })
                .collect();

            // Draw the 4 edges of the face square.
            for ei in 0..4usize {
                let (x0, y0) = corners[ei];
                let (x1, y1) = corners[(ei + 1) % 4];
                draw_edge(grid, x0, y0, x1, y1);
            }
        }
        Ok(())
    }
}
